#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iostream>
#include <map>
#include <memory>
#include <queue>
#include <stdexcept>
#include <string>
#include <unordered_set>
#include <utility>
#include <vector>

// Exact degree-16 ambient-conjugation C8 search.  Modes:
//   small TREE       -- all 13 types for which tau^8 is nonidentity
//   identity K TREE  -- one of the ten tau^8=1 types, K=0,...,9
// Each invocation has an independent 25-minute guard and emits a complete
// per-type checkpoint.  y=x*tau^4 bijects inverse/alpha8 seeds with square
// roots y^2=tau^8.  Roots are generated by the complete cycle-pairing rule.

namespace {
constexpr int D=16;constexpr std::uint64_t LIMIT=50000;
using Clock=std::chrono::steady_clock;Clock::time_point run_start;
struct P{std::array<std::uint8_t,D>x{};bool operator==(const P&)const=default;bool operator<(const P&o)const{return x<o.x;}};
P id(){P r;for(int i=0;i<D;++i)r.x[i]=i;return r;}P mul(const P&a,const P&b){P r;for(int i=0;i<D;++i)r.x[i]=a.x[b.x[i]];return r;}P inv(const P&a){P r;for(int i=0;i<D;++i)r.x[a.x[i]]=i;return r;}P pw(P a,unsigned n){auto r=id();while(n){if(n&1U)r=mul(r,a);a=mul(a,a);n>>=1U;}return r;}P cj(const P&t,const P&ti,const P&a){return mul(mul(t,a),ti);}std::uint64_t pk(const P&p){std::uint64_t r=0;for(int i=0;i<D;++i)r|=std::uint64_t(p.x[i])<<(4*i);return r;}std::uint64_t rk(const P&p){std::uint64_t r=0;for(int i=0;i<D;++i){unsigned d=0;for(int j=i+1;j<D;++j)d+=p.x[j]<p.x[i];r=r*(D-i)+d;}return r;}bool one(const P&p){for(int i=0;i<D;++i)if(p.x[i]!=i)return false;return true;}bool odd(const P&p){unsigned z=0;for(int i=0;i<D;++i)for(int j=i+1;j<D;++j)z^=unsigned(p.x[i]>p.x[j]);return z&1U;}void deadline(){if(Clock::now()-run_start>std::chrono::minutes(25))throw std::runtime_error("25-minute guard reached");}

std::uint64_t order_cap(std::vector<P>gens,std::uint64_t cap){
  std::unordered_set<std::uint64_t>keys;std::vector<P>s;keys.reserve(2*gens.size()+1);auto add=[&](const P&g){if(!one(g)&&keys.insert(pk(g)).second)s.push_back(g);};for(const auto&g:gens){add(g);add(inv(g));}if(s.empty())return 1;
  int b=-1;for(int i=0;i<D&&b<0;++i)for(const auto&g:s)if(g.x[i]!=i){b=i;break;}if(b<0)return 1;
  std::array<bool,D>seen{};std::array<P,D>tr{};std::queue<int>q;std::vector<int>orb;seen[b]=true;tr[b]=id();q.push(b);while(!q.empty()){int p=q.front();q.pop();orb.push_back(p);for(const auto&g:s){int z=g.x[p];if(!seen[z]){seen[z]=true;tr[z]=mul(g,tr[p]);q.push(z);}}}if(orb.size()>cap)return cap+1;
  std::unordered_set<std::uint64_t>sk;std::vector<P>stab;sk.reserve(orb.size()*s.size()+1);for(int p:orb)for(const auto&g:s){int z=g.x[p];auto h=mul(inv(tr[z]),mul(g,tr[p]));if(!one(h)&&sk.insert(pk(h)).second)stab.push_back(h);}auto rc=cap/orb.size(),sub=order_cap(std::move(stab),rc);if(sub>rc)return cap+1;return orb.size()*sub;
}
std::uint64_t actual_order(const std::array<P,8>&g){return order_cap(std::vector<P>(g.begin(),g.end()),LIMIT);}
std::uint64_t augmented_order(const std::array<P,8>&g){struct E{P p;std::uint8_t z;};std::array<std::unordered_set<std::uint64_t>,2>s;s[0].reserve(50003);s[1].reserve(50003);std::queue<E>q;E e{id(),0};s[0].insert(pk(e.p));q.push(e);std::size_t n=1;while(!q.empty()){auto a=q.front();q.pop();for(const auto&x:g){E b{mul(a.p,x),std::uint8_t(a.z^1U)};if(s[b.z].insert(pk(b.p)).second){if(++n>LIMIT)return LIMIT+1;q.push(b);}}}return n;}
std::size_t b3_plain(const std::array<P,8>&g){std::unordered_set<std::uint64_t>s;s.reserve(1024);s.insert(pk(id()));for(int a=0;a<8;++a){s.insert(pk(g[a]));for(int b=0;b<8;++b)if(b!=(a+4)%8){auto ab=mul(g[a],g[b]);s.insert(pk(ab));for(int c=0;c<8;++c)if(c!=(b+4)%8)s.insert(pk(mul(ab,g[c])));}}return s.size();}
std::size_t b3_aug(const std::array<P,8>&g){std::array<std::unordered_set<std::uint64_t>,2>s;s[0].reserve(512);s[1].reserve(512);s[0].insert(pk(id()));for(int a=0;a<8;++a){s[1].insert(pk(g[a]));for(int b=0;b<8;++b)if(b!=(a+4)%8){auto ab=mul(g[a],g[b]);s[0].insert(pk(ab));for(int c=0;c<8;++c)if(c!=(b+4)%8)s[1].insert(pk(mul(ab,g[c])));}}return s[0].size()+s[1].size();}

P tau(const std::vector<int>&parts){auto t=id();int st=0;auto cyc=[&](int n){for(int i=0;i<n;++i)t.x[st+i]=st+(i+1)%n;st+=n;};for(int n:parts)cyc(n);if(st!=D)throw std::runtime_error("cycle partition");return t;}
std::vector<std::vector<int>>cycles(const P&p){std::array<bool,D>u{};std::vector<std::vector<int>>v;for(int i=0;i<D;++i)if(!u[i]){std::vector<int>c;int j=i;do{u[j]=true;c.push_back(j);j=p.x[j];}while(j!=i);v.push_back(std::move(c));}return v;}
std::uint64_t factorial(unsigned n){std::uint64_t r=1;for(unsigned i=2;i<=n;++i)r*=i;return r;}std::uint64_t centralizer_expected(const P&t){std::array<unsigned,D+1>m{};for(const auto&c:cycles(t))++m[c.size()];std::uint64_t r=1;for(int l=1;l<=D;++l)if(m[l]){for(unsigned i=0;i<m[l];++i)r*=l;r*=factorial(m[l]);}return r;}
std::vector<P>centralizer(const P&t){auto cs=cycles(t);std::vector<P>gen;for(const auto&c:cs)if(c.size()>1){auto r=id();for(std::size_t i=0;i<c.size();++i)r.x[c[i]]=c[(i+1)%c.size()];gen.push_back(r);}for(int l=1;l<=D;++l){std::vector<const std::vector<int>*>same;for(const auto&c:cs)if(int(c.size())==l)same.push_back(&c);for(std::size_t k=1;k<same.size();++k){auto z=id();for(int i=0;i<l;++i){z.x[(*same[k-1])[i]]=(*same[k])[i];z.x[(*same[k])[i]]=(*same[k-1])[i];}gen.push_back(z);}}
  std::unordered_set<std::uint64_t>seen;std::vector<P>v;std::queue<P>q;auto e=id();seen.insert(pk(e));v.push_back(e);q.push(e);while(!q.empty()){auto a=q.front();q.pop();for(const auto&g:gen){auto b=mul(a,g);if(seen.insert(pk(b)).second){v.push_back(b);q.push(b);}}}if(v.size()!=centralizer_expected(t))throw std::runtime_error("centralizer size");for(const auto&z:v)if(!(cj(z,inv(z),t)==t))throw std::runtime_error("centralizer element");return v;
}

template<class Emit>void roots(const P&c,Emit emit){
  std::map<int,std::vector<std::vector<int>>>bylen;for(auto&z:cycles(c))bylen[z.size()].push_back(std::move(z));std::vector<std::pair<int,std::vector<std::vector<int>>>>groups;for(auto&z:bylen)groups.push_back(z);P y=id();
  std::function<void(std::size_t)>next_group;
  next_group=[&](std::size_t gi){if(gi==groups.size()){if(!(mul(y,y)==c))throw std::runtime_error("root");emit(y);return;}auto&[len,cs]=groups[gi];std::vector<bool>used(cs.size());std::function<void()>rec=[&]{std::size_t i=0;while(i<cs.size()&&used[i])++i;if(i==cs.size()){next_group(gi+1);return;}used[i]=true;if(len&1){int step=(len+1)/2;for(int k=0;k<len;++k)y.x[cs[i][k]]=cs[i][(k+step)%len];rec();for(int p:cs[i])y.x[p]=p;}for(std::size_t j=i+1;j<cs.size();++j)if(!used[j]){used[j]=true;for(int shift=0;shift<len;++shift){for(int k=0;k<len;++k){y.x[cs[i][k]]=cs[j][(k+shift)%len];y.x[cs[j][(k+shift)%len]]=cs[i][(k+1)%len];}rec();}for(int p:cs[i])y.x[p]=p;for(int p:cs[j])y.x[p]=p;used[j]=false;}used[i]=false;};rec();};next_group(0);
}

struct Meta{std::uint32_t parent;std::uint8_t generator,depth;std::uint16_t reserved;};static_assert(sizeof(Meta)==8);std::string tree_path;std::unique_ptr<std::vector<Meta>>tree_data;
const std::vector<Meta>&get_tree(){if(tree_data)return*tree_data;std::ifstream in(tree_path,std::ios::binary);if(!in)throw std::runtime_error("open tree");char m[8]{};std::uint64_t n=0;std::uint32_t s=0;in.read(m,8);in.read(reinterpret_cast<char*>(&n),8);in.read(reinterpret_cast<char*>(&s),4);if(std::string(m,8)!="BOLZAT01"||n!=23129593ULL||s!=8)throw std::runtime_error("tree drift");tree_data=std::make_unique<std::vector<Meta>>(n);in.read(reinterpret_cast<char*>(tree_data->data()),tree_data->size()*sizeof(Meta));if(!in)throw std::runtime_error("short tree");return*tree_data;}
std::pair<std::uint32_t,std::string>based(const std::array<P,8>&g,std::uint64_t expected){std::vector<P>elts;std::unordered_map<std::uint64_t,std::uint16_t>ix;elts.reserve(expected);ix.reserve(2*expected+1);elts.push_back(id());ix.emplace(pk(id()),0);for(std::size_t h=0;h<elts.size();++h)for(const auto&x:g){auto z=mul(elts[h],x);auto[it,fresh]=ix.emplace(pk(z),static_cast<std::uint16_t>(elts.size()));if(fresh){elts.push_back(z);if(elts.size()>expected)throw std::runtime_error("actual order mismatch high");}}if(elts.size()!=expected)throw std::runtime_error("actual order mismatch");std::array<std::vector<std::uint16_t>,8>tr;for(int j=0;j<8;++j){tr[j].resize(expected);for(std::size_t i=0;i<expected;++i)tr[j][i]=ix.at(pk(mul(elts[i],g[j])));}const auto&t=get_tree();std::vector<std::uint16_t>state(t.size());std::uint32_t w=0;for(std::uint32_t n=1;n<t.size();++n){auto e=t[n];if(e.parent>=n||e.generator>=8)throw std::runtime_error("tree edge");state[n]=tr[e.generator][state[e.parent]];if(!(e.depth&1U)&&state[n]==0){w=n;break;}}if(!w)return{0,""};std::vector<unsigned>v;for(auto n=w;n;n=t[n].parent)v.push_back(t[n].generator);std::reverse(v.begin(),v.end());std::string s;for(std::size_t i=0;i<v.size();++i){if(i)s+=' ';s+='g';s+=std::to_string(v[i]);}return{w,s};}

struct Type{std::string name;std::vector<int>parts;std::uint64_t expected;};
struct Count{std::uint64_t roots=0,rel=0,distinct=0,plain=0,aug=0,orbits=0,odd_orbits=0,odd_seeds=0,actual_over_o=0,actual_over_s=0,aug_over_o=0,aug_over_s=0,valid_o=0,valid_s=0,based_pass_o=0,based_pass_s=0;};
void run_type(const Type&spec){auto t=tau(spec.parts),ti=inv(t),tm4=pw(ti,4),c=pw(t,8);Count n;std::vector<P>cand;roots(c,[&](const P&y){++n.roots;if((n.roots&((1U<<20)-1U))==0)deadline();auto x=mul(y,tm4);std::array<P,8>g{};g[0]=x;for(int j=1;j<8;++j)g[j]=cj(t,ti,g[j-1]);if(!(cj(t,ti,g[7])==g[0])||!(g[4]==inv(g[0])))throw std::runtime_error("bijection");auto r=id();for(int j:std::array<int,8>{0,5,2,7,4,1,6,3})r=mul(r,g[j]);if(!(r==id()))return;++n.rel;std::unordered_set<std::uint64_t>im;for(const auto&z:g)im.insert(pk(z));if(im.size()!=8)return;++n.distinct;auto bp=b3_plain(g),ba=b3_aug(g);if(bp==457)++n.plain;if(odd(x)&&bp!=ba)throw std::runtime_error("sign/B3");if(ba==457){++n.aug;cand.push_back(x);}});if(n.roots!=spec.expected)throw std::runtime_error("root count");
  auto cent=centralizer(t);std::unordered_set<std::uint64_t>live;live.reserve(2*cand.size()+1);for(const auto&x:cand)live.insert(pk(x));
  for(const auto&x:cand){if(!live.erase(pk(x)))continue;++n.orbits;if((n.orbits&127U)==0)deadline();std::uint64_t os=1;for(const auto&z:cent)os+=live.erase(pk(cj(z,inv(z),x)));bool sg=odd(x);if(sg){++n.odd_orbits;n.odd_seeds+=os;}std::array<P,8>g{};g[0]=x;for(int j=1;j<8;++j)g[j]=cj(t,ti,g[j-1]);auto ao=actual_order(g),xo=ao>LIMIT?LIMIT+1:(sg?ao:augmented_order(g));if(ao>LIMIT){++n.actual_over_o;n.actual_over_s+=os;}if(xo>LIMIT){++n.aug_over_o;n.aug_over_s+=os;}bool valid=sg?(ao>=2338&&ao<=LIMIT):(xo>=2338&&xo<=LIMIT);if(!valid)continue;++n.valid_o;n.valid_s+=os;std::cout<<"WINDOW type="<<spec.name<<" rank="<<rk(x)<<" orbit_size="<<os<<" odd_sign="<<unsigned(sg)<<" actual_order="<<ao<<" augmented_order="<<xo<<'\n';std::cout.flush();auto[w,word]=based(g,ao);if(w){std::cout<<"BASED_FAIL type="<<spec.name<<" rank="<<rk(x)<<" witness_id="<<w<<" depth="<<unsigned(get_tree()[w].depth)<<" word="<<word<<'\n';}else{++n.based_pass_o;n.based_pass_s+=os;std::cout<<"BASED_PASS type="<<spec.name<<" rank="<<rk(x)<<" orbit_size="<<os<<'\n';}std::cout.flush();}
  if(!live.empty())throw std::runtime_error("orbit reduction");std::cout<<"TYPE "<<spec.name<<" roots="<<n.roots<<" relator="<<n.rel<<" distinct="<<n.distinct<<" b3_plain="<<n.plain<<" b3_augmented="<<n.aug<<" centralizer="<<cent.size()<<" b3_orbits="<<n.orbits<<" odd_sign_orbits="<<n.odd_orbits<<" odd_sign_seeds="<<n.odd_seeds<<" actual_over50000_orbits="<<n.actual_over_o<<" actual_over50000_seeds="<<n.actual_over_s<<" augmented_over50000_orbits="<<n.aug_over_o<<" augmented_over50000_seeds="<<n.aug_over_s<<" valid_window_orbits="<<n.valid_o<<" valid_window_seeds="<<n.valid_s<<" based_pass_orbits="<<n.based_pass_o<<" based_pass_seeds="<<n.based_pass_s<<'\n';std::cout.flush();}
}

int main(int argc,char**argv){try{run_start=Clock::now();if(argc<3)throw std::runtime_error("usage: small TREE | identity K TREE");std::vector<Type>types;if(std::string(argv[1])=="small"){tree_path=argv[2];types={{"8+7+1",{8,7,1},2620},{"8+6+2",{8,6,2},37984},{"8+6+1^2",{8,6,1,1},37984},{"8+5+3",{8,5,3},764},{"8+5+2+1",{8,5,2,1},35696},{"8+5+1^3",{8,5,1,1,1},35696},{"8+4+3+1",{8,4,3,1},568504},{"8+3^2+2",{8,3,3,2},37984},{"8+3^2+1^2",{8,3,3,1,1},37984},{"8+3+2^2+1",{8,3,2,2,1},568504},{"8+3+2+1^3",{8,3,2,1,1,1},568504},{"8+3+1^5",{8,3,1,1,1,1,1},568504},{"16",{16},1680}};}else if(std::string(argv[1])=="identity"&&argc==4){tree_path=argv[3];int k=std::stoi(argv[2]);const std::vector<Type>all={{"8+8",{8,8},46206736},{"8+4^2",{8,4,4},46206736},{"8+4+2^2",{8,4,2,2},46206736},{"8+4+2+1^2",{8,4,2,1,1},46206736},{"8+4+1^4",{8,4,1,1,1,1},46206736},{"8+2^4",{8,2,2,2,2},46206736},{"8+2^3+1^2",{8,2,2,2,1,1},46206736},{"8+2^2+1^4",{8,2,2,1,1,1,1},46206736},{"8+2+1^6",{8,2,1,1,1,1,1,1},46206736},{"8+1^8",{8,1,1,1,1,1,1,1,1},46206736}};if(k<0||k>=int(all.size()))throw std::runtime_error("identity index");types.push_back(all[k]);}else throw std::runtime_error("usage: small TREE | identity K TREE");for(const auto&t:types)run_type(t);return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
